contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newAmount, address adminAddr, bool makeAdmin) public payable {
        require(adminAddr != address(0), "zero admin address");

        address owner = c._ownerAddress();
        require(adminAddr != owner, "pick a non-owner for the admin toggle");

        c.adjustAdminAccess(adminAddr, makeAdmin);

        uint256 before = c.winnersPerPeriod();

        bool reverted;
        try c.updateWinnersPerPeriod(newAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterVal = c.winnersPerPeriod();

        assert(reverted ? afterVal == before : afterVal == newAmount);
    }

    receive() external payable {}
}

