contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public {
        uint256 roundBefore = c.roundId();
        uint256 winnersPerPeriod = c.winnersPerPeriod();

        // Setup: make msg.sender (this contract) an admin, since pickWinner requires isAdmin[msg.sender].
        c.adjustAdminAccess(address(this), true);

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // A revert must mean the winners array length did not match the configured number.
            assert(winners.length != winnersPerPeriod);
        } else {
            // On success, roundId advanced by exactly one and the recorded winners for the
            // completed round are exactly the input winners array (length and membership).
            assert(c.roundId() == roundBefore + 1);
            assert(c.winnerAddresses(roundBefore).length == winnersPerPeriod);
            assert(c.winnerAddresses(roundBefore).length == winners.length);
        }
    }

    receive() external payable {}
}

