contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public {
        uint256 roundBefore = c.roundId();
        uint256 wpp = c.winnersPerPeriod();
        uint256 totalBefore = c.totalPoints();

        // Setup: make this contract an admin so that pickWinner is authorized.
        c.adjustAdminAccess(address(this), true);

        // Record the points of each id we will ask to pick.
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumBefore += c.fighterPoints(winners[i]);
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // The only length-related precondition is wrong here.
            assert(winners.length != wpp);
        } else {
            // Successful pick: array length matched, round advanced by one,
            // and totalPoints shrank by exactly the cleared fighter points.
            assert(winners.length == wpp);
            assert(c.roundId() == roundBefore + 1);
            assert(c.totalPoints() == totalBefore - sumBefore);
        }
    }

    receive() external payable {}
}

