contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address caller,
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes,
        uint256 preRoundId,
        uint32 preClaimed
    ) public payable {
        require(caller != address(0), "caller must be nonzero");
        require(caller != address(this), "caller must differ from test contract");
        require(modelURIs.length == modelTypes.length, "URI/type length mismatch");
        require(modelURIs.length == customAttributes.length, "URI/attribute length mismatch");
        require(preRoundId <= c.roundId(), "parameter must not exceed current roundId");
        require(preClaimed <= c.roundId(), "preClaimed must not exceed current roundId");

        uint256 observedRoundId = c.roundId();
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint32 claimedAfter = c.numRoundsClaimed(address(this));

        if (!reverted) {
            assert(
                claimedAfter == uint32(observedRoundId) &&
                uint32(observedRoundId) - claimedAfter == 0 &&
                (uint32(observedRoundId) >= claimedAfter)
            );
        } else {
            assert(claimedAfter == 0);
        }
    }

    receive() external payable {}
}

