contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _ownerAddress, uint256 fighterId, uint256 points, uint256 winnerId) public payable {
        // Setup: make _ownerAddress an admin so it can call pickWinner, and seed points via a callable public entry.
        c.adjustAdminAccess(address(this), true);

        // Seed points using the only public state-changing path we can reach through c.addPoints.
        // addPoints only works for the RankedBattle address, so we cannot seed fighterPoints for an arbitrary fighter.
        // Use the default seeded state: fighterPoints[winnerId] may be whatever the fresh deployment sets.
        uint256 beforePoints = c.fighterPoints(winnerId);
        uint256 beforeTotal = c.totalPoints();

        // Capture whether the winner selection completes; pickWinner may revert for invalid winner arrays.
        uint256[] memory winners = new uint256[](1);
        winners[0] = winnerId;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterPoints = c.fighterPoints(winnerId);
            uint256 afterTotal = c.totalPoints();
            assert(afterPoints == 0 && afterTotal + beforePoints == beforeTotal);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

