contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerId) public payable {
        require(true);

        // Setup: grant admin role to this contract so pickWinner can be called.
        // isAdmin is public and defaults to false for this contract, but _ownerAddress
        // is the deployer. adjustAdminAccess requires msg.sender == _ownerAddress,
        // so we cannot call it from here. However, pickWinner requires isAdmin[msg.sender];
        // since c was deployed by this test contract in the checker's setup, assume
        // the owner is this contract (constructor of C sets isAdmin[ownerAddress] = true
        // and ownerAddress is the deployer). If not admin, the call will revert and we
        // skip the rule check by asserting the revert path? But the task requires a general rule.
        // Instead, use the public updateWinnersPerPeriod? Also requires isAdmin.
        // We can't guarantee isAdmin[address(this)] without constructor wiring. In the
        // checker's fresh deployment, the deployer is InvMutTest, so _ownerAddress is
        // address(this) and isAdmin[address(this)] is true. So we are admin.

        // Read before-state for roundId and whether selection for current round is complete.
        uint256 ridBefore = c.roundId();
        bool completeBefore = c.isSelectionComplete(ridBefore);

        // Build a winners array of length winnersPerPeriod with the given winnerId repeated.
        // winnersPerPeriod is public and we read it; it is 2 by default.
        uint256 wpp = c.winnersPerPeriod();
        uint256[] memory winners = new uint256[](wpp);
        for (uint256 i = 0; i < wpp; i++) {
            winners[i] = winnerId;
        }

        // The deciding call: pickWinner. It may revert if winnerId is not a valid token
        // (ownerOf reverts). In that case we should not assert the success rule.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if pickWinner did not revert, then for the round that was
        // selected (ridBefore), isSelectionComplete must now be true, and roundId
        // must have advanced by exactly 1. If it reverted, isSelectionComplete for
        // ridBefore must be unchanged.
        uint256 ridAfter = c.roundId();
        bool completeAfter = c.isSelectionComplete(ridBefore);

        if (!reverted) {
            assert(completeAfter == true && ridAfter == ridBefore + 1);
        } else {
            assert(completeAfter == completeBefore && ridAfter == ridBefore);
        }
    }

    receive() external payable {}
}

