contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerId, uint256 wpp, uint256 extra) public payable {
        require(wpp >= 2 && wpp <= 12);
        require(extra == 0);

        c.updateWinnersPerPeriod(wpp);

        uint256 ridBefore = c.roundId();
        uint256 wppNow = c.winnersPerPeriod();

        uint256[] memory winners = new uint256[](wppNow);
        for (uint256 i = 0; i < wppNow; i++) {
            winners[i] = winnerId;
        }

        bool callOk;
        try c.pickWinner(winners) { callOk = true; } catch { callOk = false; }

        bool completeBefore = c.isSelectionComplete(ridBefore);
        uint256 ridAfter = c.roundId();

        uint256[] memory emptyWinners = new uint256[](0);
        c.pickWinner(emptyWinners);

        uint256 ridAfter2 = c.roundId();

        assert(
            (callOk && completeBefore && ridAfter == ridBefore + 1 && ridAfter2 == ridBefore + 1)
            ||
            (!callOk && !completeBefore && ridAfter == ridBefore && ridAfter2 == ridBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerId, uint256 wpp, uint256 extra) public payable {
        require(wpp >= 2 && wpp <= 12);
        require(extra == 0);

        c.updateWinnersPerPeriod(wpp);

        uint256 ridBefore = c.roundId();
        uint256 wppNow = c.winnersPerPeriod();

        uint256[] memory winners = new uint256[](wppNow);
        for (uint256 i = 0; i < wppNow; i++) {
            winners[i] = winnerId;
        }

        bool callOk;
        try c.pickWinner(winners) { callOk = true; } catch { callOk = false; }

        bool completeAfter = c.isSelectionComplete(ridBefore);
        uint256 ridAfter = c.roundId();

        assert(
            (callOk && completeAfter && ridAfter == ridBefore + 1)
            || (!callOk && !completeAfter && ridAfter == ridBefore)
        );
    }

    receive() external payable {}
}

