contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newWinnersPerPeriod, uint256[] calldata winners) public {
        // Only admins can change winnersPerPeriod; msg.sender (this contract) is not an admin.
        bool updateReverted;
        try c.updateWinnersPerPeriod(newWinnersPerPeriod) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // Read the value that is in effect for the subsequent pickWinner attempt.
        uint256 effectiveWinnersPerPeriod = c.winnersPerPeriod();

        bool pickReverted;
        try c.pickWinner(winners) {
            pickReverted = false;
        } catch {
            pickReverted = true;
        }

        // General rule: for a fresh, non-admin caller,
        // - the unpermissioned winnersPerPeriod update must revert,
        // - pickWinner must revert iff the number of supplied winners is not exactly the
        //   current winnersPerPeriod (when length matches, the admin check is satisfied
        //   because the freshly-deployed C marks the deployer, which is this test contract,
        //   as admin, so the call completes).
        assert(
            updateReverted &&
            (pickReverted == (winners.length != effectiveWinnersPerPeriod))
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newWinnersPerPeriod, uint256[] calldata winners) public {
        // This test contract is the deployer and therefore an admin of the fresh C.
        // A non-deployer would be non-admin; here we rely on the admin path only for
        // the length rule, and we check the permission effect by probing an admin-only setter
        // with a state-reading comparison rather than reverting on admin status.
        uint256 roundBefore = c.roundId();
        bool completeBefore = c.isSelectionComplete(roundBefore);
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();

        bool pickReverted;
        try c.pickWinner(winners) {
            pickReverted = false;
        } catch {
            pickReverted = true;
        }

        uint256 roundAfter = c.roundId();
        uint256 winnersPerPeriodAfter = c.winnersPerPeriod();

        // General rule: pickWinner reverts exactly when the supplied winners array
        // length differs from the configured winnersPerPeriod (or the current round
        // already has its selection complete). On success it advances roundId by 1,
        // and the admin-only winnersPerPeriod setter is untouched by this call.
        assert(
            (pickReverted == (winners.length != winnersPerPeriodBefore || completeBefore)) &&
            (pickReverted ? (roundAfter == roundBefore) : (roundAfter == roundBefore + 1)) &&
            (winnersPerPeriodAfter == winnersPerPeriodBefore)
        );
    }
}

