contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address claimer, uint256 lo, uint256 hi) public payable {
        require(claimer != address(0));
        uint256 roundId = c.roundId();
        require(lo <= hi);
        require(hi <= roundId);
        uint256 beforeClaimed = c.numRoundsClaimed(claimer);
        uint256 expected = 0;
        for (uint256 r = lo; r < hi; r++) {
            uint256 len = c.winnerAddresses(r).length;
            for (uint256 j = 0; j < len; j++) {
                if (c.winnerAddresses(r) [j] == claimer) {
                    expected += 1;
                }
            }
        }
        uint256 rewards = c.getUnclaimedRewards(claimer);
        assert(rewards >= expected);
        assert(beforeClaimed == 0 || rewards == expected);
    }
    receive() external payable {}
}

