        // to us (only rankedBattleAddress can call addPoints). Instead we use the public
        // surface to first observe and then require that points were set through addPoints.
        // Since addPoints is restricted, we cannot call it. Therefore we only rely on
        // pickWinner's observable effect on fighterPoints.

        // Read the fighterPoints value before pickWinner for the given tokenId.
        uint256 pointsBefore = c.fighterPoints(tokenId);

        // Read the current roundId.
        uint256 roundBefore = c.roundId();

        // Read whether selection is already complete for the current round.
        bool alreadyComplete = c.isSelectionComplete(roundBefore);

        // If the round is already complete, pickWinner will revert; skip.
        // We want to test the successful path.
        // winnersPerPeriod must be >= 1.
        uint256 wpp = c.winnersPerPeriod();
        require(wpp >= 1);

        // Build the winners array of length winnersPerPeriod, all the same tokenId.
        uint256[] memory winners = new uint256[](wpp);
        for (uint256 i = 0; i < wpp; i++) {
            winners[i] = tokenId;
        }

        // Ensure msg.sender is an admin so pickWinner does not revert on the admin check.
        // The test contract is the deployer, but the owner is set in the constructor as
        // ownerAddress, which is this contract (since we deploy C ourselves).
        // c.adjustAdminAccess(msg.sender, true) requires msg.sender == _ownerAddress.
        // To be safe, we call pickWinner only if msg.sender is admin.
        // If not admin, this will revert and the test's assert wouldn't run.
        // However, the checker runs run() once, and this contract is the deployer of c,
        // so _ownerAddress == msg.sender (this contract) if the constructor was called with msg.sender.
        // We assume that is the case: the constructor sets _ownerAddress = ownerAddress,
        // and the test contract deploys C, so we can pass address(this) as ownerAddress.
        // But the template says the checker deploys a fresh c and this contract deployed c.
        // Therefore this contract is the owner, and isAdmin[this] is true by constructor.

        // Require not already complete to avoid revert.
        require(!alreadyComplete);

        // Call pickWinner.
        c.pickWinner(winners);

        // After pickWinner, fighterPoints for each winner should be zero.
        uint256 pointsAfter = c.fighterPoints(tokenId);

        // General rule: after pickWinner selects tokenId as a winner,
        // fighterPoints[tokenId] is reset to 0.
        assert(pointsAfter == 0);
    }

    receive() external payable {}
}

