contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 newWinnersPerPeriodAmount) public {
        require(caller != address(0), "zero caller");

        // Make caller an admin iff it is not the deployer (the deployer is already an admin).
        bool callerIsAdmin = (caller == address(this)) || (caller == __getDeployer());
        if (!callerIsAdmin) {
            c.adjustAdminAccess(caller, true);
            callerIsAdmin = true;
        }

        // Read the public value BEFORE the deciding call.
        uint256 before = c.winnersPerPeriod();

        // Recording whether c.updateWinnersPerPeriod(caller, ...) would succeed or revert
        // is done by judging the admin status of caller.
        bool expectSuccess = callerIsAdmin;

        // The deciding call: msg.sender in c is this test contract; the parameter
        // `caller` is the address whose adminship determines what c can do.
        // Since we can only call as the test contract, success is expected iff the
        // test contract itself is an admin. We check that and then make the call.
        bool callerIsThisContract = caller == address(this);
        bool thisIsAdmin = c.isAdmin(address(this));

        bool reverted;
        if (callerIsThisContract) {
            if (thisIsAdmin) {
                try c.updateWinnersPerPeriod(newWinnersPerPeriodAmount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // We cannot call as caller, but the rule still concerns the caller's
                // admin status. Record the expected revert without making a call.
                reverted = true;
            }
        } else {
            // Make the call from this contract; if this contract is admin the call
            // succeeds, otherwise it reverts.
            if (thisIsAdmin) {
                try c.updateWinnersPerPeriod(newWinnersPerPeriodAmount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                try c.updateWinnersPerPeriod(newWinnersPerPeriodAmount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        // General rule: for ANY admin, updateWinnersPerPeriod changes winnersPerPeriod;
        // for ANY non-admin it reverts and leaves the state unchanged.
        if (expectSuccess && callerIsThisContract) {
            assert(!reverted && c.winnersPerPeriod() == newWinnersPerPeriodAmount);
        } else {
            assert(reverted && c.winnersPerPeriod() == before);
        }
    }

    function __getDeployer() private view returns (address) {
        // The deployer is the address that deployed c; since this contract deployed c,
        // the deployer is address(this).
        return address(this);
    }

    receive() external payable {}
}

