    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenA, uint256 tokenB) public payable {
        require(tokenA != tokenB);
        require(c.winnersPerPeriod() == 2);
        require(!c.isSelectionComplete(c.roundId()));

        uint256 beforeA = c.fighterPoints(tokenA);
        uint256 beforeB = c.fighterPoints(tokenB);
        uint256 beforeTotal = c.totalPoints();

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenA;
        winners[1] = tokenB;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalPoints();

        assert(
            !reverted
                ? (afterTotal == beforeTotal - beforeA - beforeB)
                : (afterTotal == beforeTotal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint32 probeKey, string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public {
        require(probeKey != uint32(uint160(address(this))));

        uint32 beforeProbe = c.numRoundsClaimed(address(uint160(probeKey)));
        uint32 beforeSelf = c.numRoundsClaimed(address(this));
        uint256 roundIdBefore = c.roundId();

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint32 afterProbe = c.numRoundsClaimed(address(uint160(probeKey)));
        uint32 afterSelf = c.numRoundsClaimed(address(this));
        uint256 roundIdAfter = c.roundId();

        assert(
            afterProbe >= beforeProbe &&
            afterSelf >= beforeSelf &&
            afterSelf <= roundIdBefore &&
            roundIdAfter == roundIdBefore
        );
    }
}

