contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerId, uint256 roundsBefore) public {
        require(roundsBefore == 0);

        address me = address(this);
        c.adjustAdminAccess(me, true);

        uint256 currentRoundBefore = c.roundId();
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        require(winnersPerPeriodBefore == 1);

        uint256[] memory winners = new uint256[](1);
        winners[0] = winnerId;

        bool revertedFirst;
        try c.pickWinner(winners) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        uint256 currentRoundAfter = c.roundId();
        bool completeAfter = c.isSelectionComplete(currentRoundBefore);

        bool revertedSecond;
        try c.pickWinner(winners) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        assert(!revertedFirst && completeAfter && currentRoundAfter == currentRoundBefore + 1 && revertedSecond);
    }
}

