    constructor(C _c) {
        c = _c;
    }

    function run(address adminAddress, bool access) public payable {
        address owner = c._ownerAddress();
        bool before = c.isAdmin(adminAddress);

        bool reverted;
        if (msg.sender != owner) {
            try c.adjustAdminAccess(adminAddress, access) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            c.adjustAdminAccess(adminAddress, access);
            reverted = false;
        }

        bool after = c.isAdmin(adminAddress);

        assert(reverted || after == access || (msg.sender != owner && before == after));
    }
}

